		// ---------- avatar mapping ------------------------------------------
		// member name -> avatar key by prefix: lead/hanlin/works/dali/yushi;
		// an unmatched name gets a neutral "unassigned" mark instead of a bureau
		// avatar, so a stranger is never mistakable for the Lead.
		const AVATAR_KEYS = ['lead', 'hanlin', 'works', 'dali', 'yushi'];
		const ROLE_PREFIXES = { lead: ['首辅', '内阁首辅'], hanlin: ['翰林院', '编修'], works: ['工部', '主事'], dali: ['大理寺', '评事'], yushi: ['都察院', '御史'] };
		const NEUTRAL_CACHE = new Map();
		function neutralAvatar(name) {
			const text = typeof name === 'string' ? name.trim() : '';
			const glyph = (Array.from(text)[0] || '?').toUpperCase();
			const cached = NEUTRAL_CACHE.get(glyph);
			if (cached !== undefined) return cached;
			const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">'
				+ '<rect width="128" height="128" fill="#6b7280"/>'
				+ '<rect x="5" y="5" width="118" height="118" fill="none" stroke="#d1d5db" stroke-width="4" stroke-dasharray="10 8"/>'
				+ '<text x="64" y="66" fill="#f9fafb" font-family="sans-serif" font-size="54" font-weight="600"'
				+ ' text-anchor="middle" dominant-baseline="central">'
				+ glyph.replace(/[&<>"]/g, '') + '</text></svg>';
			const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
			NEUTRAL_CACHE.set(glyph, url);
			return url;
		}
		function avatarFor(name) {
			const key = bureauOfName(name);
			if (key !== '') {
				const custom = memberConfig.avatars.get(key) || '';
				if (custom !== '') return custom;
				// A saved display name has no office prefix, so the built-in lookup
				// below would miss it; fall back to this member's built-in portrait.
				const text = typeof name === 'string' ? name.trim() : '';
				if (text !== '' && !text.startsWith(key) && !ROLE_PREFIXES[key].some((prefix) => text.startsWith(prefix))) return AVATARS[key];
			}
			const text = typeof name === 'string' ? name.trim() : '';
			for (const k of AVATAR_KEYS) if (text.startsWith(k) || ROLE_PREFIXES[k].some((prefix) => text.startsWith(prefix))) return AVATARS[k];
			return neutralAvatar(text);
		}
		function isPlaceholder(name) {
			const text = typeof name === 'string' ? name : '';
			return AVATAR_KEYS.some((key) => text.startsWith(key) && AVATAR_PLACEHOLDERS.includes(key));
		}

		// ---------- member personalization (settings-backed) -----------------
