					const wrap = slots[i];
					const img = wrap.tagName === 'IMG' ? wrap : wrap.querySelector('img');
					const row = typeof wrap.closest === 'function' ? wrap.closest('button') : null;
					const nameNode = row ? row.querySelector('[class*="memberNameText"]') : null;
